<?php
/** لیست حقوق دومرحله‌ای (PAY-05..08): محاسبه، قفل و خروجی، تعدیل، نسخهٔ تازه، مقایسه، تأیید نهایی، پرداخت، برگشت. */
namespace Agah\Erp\Http;
use Agah\Erp\Core\{Ctx,Db,Jalali,Money,Request};
use Agah\Erp\Modules\Payroll\PayrollRunService as R;
if(!defined('ABSPATH'))exit;
$id=Request::int('get','id');$unit=Ctx::unit();$f=fn($v)=>Money::fmt((int)$v,$unit);
$exportLink=function($type,$run,$label,$extra=[])use($cid){return '<a class="btn btn-outline btn-sm" href="'.esc_url(add_query_arg(array_merge($extra,['payroll_export'=>$type,'run'=>$run,'format'=>'xlsx','_n'=>wp_create_nonce('agah_payroll_export_'.$cid.'_'.$run.'_'.$type)]))).'">'.esc_html($label).'</a> ';};
?>
<section class="erp-card"><h2>لیست حقوق دومرحله‌ای</h2>
<p class="muted">۱) محاسبهٔ اولیه ← ۲) «قفل و ارسال»: نسخه قفل می‌شود و فهرست مالیات/بیمه از آن گرفته می‌شود ← ۳) ورود مالیات اعلامی و تعدیل‌ها با دلیل ← ۴) محاسبهٔ دوباره (نسخهٔ تازه؛ نسخهٔ قفل‌شده دست نمی‌خورد) ← ۵) تأیید نهایی: فیش هر نفر و یک سند ← ۶) فایل بانک و پرداخت. اصلاح پس از تأیید فقط با «برگشت» ثبت‌شده و لیست تازه. فایل‌های بیمه و مالیات <b>آزمایشی</b>اند تا نمونهٔ رسمی برسد.</p>
<?php if(Ctx::can('payroll.edit')): ?><form method="post" class="erp-form"><?php self::form('module_run_create',$cid,'payroll_runs'); self::input('period_key','ماه (مثلاً 1405-07)','','text','required maxlength="7" dir="ltr"'); ?><button type="submit" class="btn btn-primary">محاسبهٔ اولیهٔ لیست ماه</button></form><?php endif; ?>
<table class="erp-table"><thead><tr><th>شماره</th><th>ماه</th><th>وضعیت</th><th>نسخه</th><th>تاریخ سند</th></tr></thead><tbody><?php foreach(R::runs($cid) as $r): ?><tr><td><a href="<?php echo esc_url(agah_erp_url(['c'=>$cid,'p'=>'payroll_runs','id'=>$r['id']])); ?>"><?php echo esc_html(Money::toFa((string)$r['id'])); ?></a></td><td><?php echo esc_html($r['period_key']); ?></td><td><?php echo esc_html(R::STATUS[$r['status']]??$r['status']); ?></td><td><?php echo esc_html(Money::toFa((string)$r['version'])); ?></td><td><?php echo esc_html($r['doc_date']?Jalali::format($r['doc_date']):'—'); ?></td></tr><?php endforeach; ?></tbody></table></section>

<?php if($id): $r=R::run($cid,$id);$v=Request::int('get','version')?:(int)$r['version'];$lines=R::lines($cid,$id,$v);$st=$r['status'];
$tot=['gross'=>0,'insurance_employee'=>0,'insurance_employer'=>0,'tax'=>0,'deductions'=>0,'net'=>0];foreach($lines as $l)if($l['status']==='ok')foreach($tot as $k=>$x)$tot[$k]+=(int)$l[$k]; ?>
<section class="erp-card"><h2>لیست حقوق <?php echo esc_html($r['period_key']); ?> — <?php echo esc_html(R::STATUS[$st]??$st); ?></h2>
<p>نسخهٔ نمایش: <?php for($i=1;$i<=(int)$r['version'];$i++): ?><a class="btn btn-sm <?php echo $i===$v?'btn-primary':'btn-outline'; ?>" href="<?php echo esc_url(add_query_arg(['version'=>$i])); ?>"><?php echo esc_html(Money::toFa((string)$i).((int)$r['sent_version']===$i?' (قفل‌شده)':'')); ?></a> <?php endfor; ?>
<?php if((int)$r['pending']): ?><span class="erp-err">تعدیل تازه ثبت شده؛ پیش از تأیید، «محاسبهٔ دوباره» بزنید.</span><?php endif; ?></p>
<div class="erp-scroll"><table class="erp-table"><thead><tr><th>کارمند</th><th>ناخالص</th><th>بیمهٔ کارمند</th><th>بیمهٔ کارفرما</th><th>مالیات</th><th>کسور</th><th>خالص</th><th>جزئیات</th></tr></thead><tbody>
<?php foreach($lines as $l): $c=json_decode((string)$l['calc'],true); ?><tr><td><a href="<?php echo esc_url(agah_erp_url(['c'=>$cid,'p'=>'hr_profile','id'=>$l['employee_id']])); ?>"><?php echo esc_html($l['employee_name']); ?></a></td>
<?php if($l['status']!=='ok'): ?><td colspan="7" class="erp-err"><?php echo esc_html($l['error']); ?></td><?php else: ?><td><?php echo esc_html($f($l['gross'])); ?></td><td><?php echo esc_html($f($l['insurance_employee'])); ?></td><td><?php echo esc_html($f($l['insurance_employer'])); ?></td><td><?php echo esc_html($f($l['tax']).($c['tax_source']==='declared'?' (اعلامی)':'')); ?></td><td><?php echo esc_html($f($l['deductions'])); ?></td><td><b><?php echo esc_html($f($l['net'])); ?></b></td>
<td><details><summary>خط محاسبه</summary><ul><?php foreach($c['lines'] as $x): ?><li><?php echo esc_html(($x['kind']==='deduction'?'− ':'+ ').$x['label'].': '.$f($x['amount']).(isset($x['basis'])?' ('.$x['basis'].')':'').(!empty($x['reason'])?' — '.$x['reason']:'')); ?></li><?php endforeach; ?>
<li><?php echo esc_html('پایهٔ بیمه: '.$f($c['insured']).' — درآمد مشمول مالیات: '.$f($c['taxable']).' — مالیات محاسبه‌شده: '.$f($c['computed_tax']).' — نسخهٔ تعرفه: '.Money::toFa((string)$c['tariff_version'])); ?></li></ul></details></td><?php endif; ?></tr><?php endforeach; ?>
</tbody><tfoot><tr><th>جمع (<?php echo esc_html(Money::unitLabel($unit)); ?>)</th><?php foreach($tot as $x): ?><th><?php echo esc_html($f($x)); ?></th><?php endforeach; ?><th></th></tr></tfoot></table></div>
<div class="erp-actions erp-no-print">
<?php if(in_array($st,['calculated','sent','adjusting'],true)&&Ctx::can('payroll.edit')): ?><form method="post" class="erp-inline-form"><?php self::form('module_run_recalc',$cid,'payroll_runs',$id); ?><button type="submit" class="btn btn-outline"><?php echo $st==='calculated'?'محاسبهٔ دوباره':'محاسبهٔ دوباره (نسخهٔ تازه)'; ?></button></form><?php endif; ?>
<?php if($st==='calculated'&&Ctx::can('payroll.approve')): ?><form method="post" class="erp-inline-form"><?php self::form('module_run_send',$cid,'payroll_runs',$id); ?><button type="submit" class="btn btn-primary" data-confirm="نسخهٔ فعلی قفل می‌شود و دیگر تغییر نمی‌کند. ادامه می‌دهید؟">قفل و ارسال (پایان مرحلهٔ ۱)</button></form><?php endif; ?>
<?php if(in_array($st,['sent','adjusting','final','paid'],true)&&Ctx::can('payroll.sensitive')&&Ctx::can('payroll.export')){echo $exportLink('tax',$id,'فهرست مالیات (آزمایشی، نسخهٔ قفل‌شده)');echo $exportLink('insurance',$id,'فهرست بیمه (آزمایشی، نسخهٔ قفل‌شده)');} ?>
<?php if(in_array($st,['final','paid'],true)&&Ctx::can('payroll.pay')): $bc=R::bankCheck($cid,$id); if($bc['errors']): ?><p class="erp-err"><?php echo esc_html('پیش از فایل بانک: '.implode(' ',$bc['errors'])); ?></p><?php else: echo $exportLink('bank',$id,'فایل پرداخت گروهی بانک (آزمایشی)'); endif; endif; ?>
</div>
<?php if(in_array($st,['sent','adjusting'],true)&&Ctx::can('payroll.approve')): ?>
<form method="post" class="erp-form"><h3>تعدیل یا مالیات اعلامی یک نفر (مرحلهٔ ۲)</h3><?php self::form('module_run_adjust',$cid,'payroll_runs',$id); self::select('employee_id','کارمند',array_column(array_filter($lines,fn($l)=>$l['status']==='ok'),'employee_name','employee_id'),0); self::input('tax_override','مالیات اعلامی'.' ('.Money::unitLabel($unit).'؛ خالی = محاسبهٔ سامانه)','','text'); self::input('earning','تعدیل افزایشی'.' ('.Money::unitLabel($unit).')','0','text'); self::input('deduction','تعدیل کاهشی'.' ('.Money::unitLabel($unit).')','0','text'); self::input('reason','دلیل (الزامی)','','text','required minlength="5" maxlength="300"'); ?><button type="submit" class="btn btn-outline">ثبت تعدیل</button></form>
<?php $adj=R::adjustments($cid,$id); if($adj): ?><table class="erp-table"><thead><tr><th>کارمند</th><th>مالیات اعلامی</th><th>افزایش</th><th>کاهش</th><th>دلیل</th></tr></thead><tbody><?php foreach($adj as $a): ?><tr><td><?php echo esc_html($a['employee_name']); ?></td><td><?php echo esc_html($a['tax_override']!==null?$f($a['tax_override']):'—'); ?></td><td><?php echo esc_html($f($a['earning'])); ?></td><td><?php echo esc_html($f($a['deduction'])); ?></td><td><?php echo esc_html($a['reason']); ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?>
<form method="post" class="erp-form"><?php self::form('module_run_finalize',$cid,'payroll_runs',$id); [, , $end]=\Agah\Erp\Modules\Payroll\PayrollService::period($r['period_key']); self::input('doc_date','تاریخ سند حقوق',Jalali::format($end,false),'text','required data-jalali maxlength="10"'); ?><button type="submit" class="btn btn-primary" data-confirm="فیش‌ها و سند حقوق صادر می‌شود. ادامه می‌دهید؟">تأیید نهایی و صدور سند</button></form>
<?php endif; ?>
<?php if((int)$r['version']>1): $va=Request::int('get','cmp_a')?:1;$vb=Request::int('get','cmp_b')?:(int)$r['version']; ?>
<h3>مقایسهٔ نسخه‌ها</h3><form method="get" action="<?php echo esc_url(agah_erp_url()); ?>" class="erp-filter"><input type="hidden" name="page_id" value="<?php echo (int)get_option('agah_erp_page_id'); ?>"><input type="hidden" name="c" value="<?php echo (int)$cid; ?>"><input type="hidden" name="p" value="payroll_runs"><input type="hidden" name="id" value="<?php echo (int)$id; ?>"><label>نسخهٔ الف<input type="number" name="cmp_a" min="1" max="<?php echo (int)$r['version']; ?>" value="<?php echo (int)$va; ?>"></label><label>نسخهٔ ب<input type="number" name="cmp_b" min="1" max="<?php echo (int)$r['version']; ?>" value="<?php echo (int)$vb; ?>"></label><button type="submit" class="btn btn-outline">مقایسه</button></form>
<table class="erp-table"><thead><tr><th>کارمند</th><th>ناخالص الف → ب</th><th>مالیات الف → ب</th><th>خالص الف → ب</th><th>تفاوت خالص</th></tr></thead><tbody><?php foreach(R::compare($cid,$id,$va,$vb) as $o): ?><tr><td><?php echo esc_html($o['name']); ?></td><?php foreach(['gross','tax','net'] as $k): ?><td><?php echo esc_html($f($o['v1'][$k]??0).' → '.$f($o['v2'][$k]??0)); ?></td><?php endforeach; ?><td><?php echo esc_html($f($o['diff_net'])); ?></td></tr><?php endforeach; ?></tbody></table>
<?php endif; ?>
<?php if($st==='final'&&Ctx::can('payroll.pay')): $banks=[0=>'انتخاب حساب بانکی'];foreach(Db::rows('SELECT id,name FROM '.Db::t('treasury_accounts')." WHERE company_id=%d AND kind='bank' AND is_active=1 ORDER BY code",$cid) as $b)$banks[$b['id']]=$b['name']; ?>
<form method="post" class="erp-form"><h3>پرداخت</h3><?php self::form('module_run_pay',$cid,'payroll_runs',$id); self::select('treasury_account_id','از حساب بانکی',$banks,0); self::input('doc_date','تاریخ پرداخت',Jalali::format(Jalali::today(),false),'text','required data-jalali maxlength="10"'); ?><button type="submit" class="btn btn-primary" data-confirm="سند پرداخت حقوق صادر می‌شود. ادامه می‌دهید؟">ثبت پرداخت</button></form><?php endif; ?>
<?php if(in_array($st,['calculated','sent','adjusting','final'],true)&&Ctx::can('payroll.delete')): ?><details><summary>برگشت لیست (اصلاحیه)</summary><form method="post" class="erp-form"><?php self::form('module_run_reverse',$cid,'payroll_runs',$id); self::input('reason','دلیل برگشت','','text','required minlength="5" maxlength="300"'); ?><button type="submit" class="btn btn-danger" data-confirm="سند و فیش‌های این لیست باطل (نه حذف) می‌شوند و می‌توانید لیست تازهٔ همین ماه را بسازید. ادامه می‌دهید؟">برگشت</button></form></details><?php endif; ?>
<?php if($r['voucher_id']&&Ctx::can('voucher.view')): ?><p><a href="<?php echo esc_url(agah_erp_url(['c'=>$cid,'p'=>'voucher_view','id'=>$r['voucher_id']])); ?>">سند حقوق</a><?php if($r['pay_voucher_id']): ?> · <a href="<?php echo esc_url(agah_erp_url(['c'=>$cid,'p'=>'voucher_view','id'=>$r['pay_voucher_id']])); ?>">سند پرداخت</a><?php endif; ?></p><?php endif; ?>
<?php if($st==='reversed'): ?><p class="erp-err">برگشت‌خورده: <?php echo esc_html($r['reverse_reason']); ?></p><?php endif; ?>
</section>
<?php endif; ?>
